-- A catalogue as 0.15 left it, on the fixture layout's tags: schema from tag v0.15.0, rows for what `--make-layout` writes.
-- `@music@`, `@incoming@`, `@second@` are the folders, and size and mtime of 0 the files': `data_0_15` in tests/e2e.rs fills them in.
-- Tracks count down from the order of a walk: a catalogue made afresh counts up, so a lost one shows.
CREATE TABLE folders (id INTEGER PRIMARY KEY, path TEXT NOT NULL);
CREATE TABLE files ( folder INTEGER NOT NULL, rel TEXT NOT NULL, size INTEGER NOT NULL, mtime INTEGER NOT NULL, state INTEGER NOT NULL DEFAULT 0, format TEXT, bitrate INTEGER, duration_ms INTEGER, error TEXT, issue TEXT, issue_detail TEXT, track INTEGER, gone_at INTEGER, trashed TEXT, PRIMARY KEY (folder, rel)) WITHOUT ROWID;
CREATE TABLE cover_files ( folder INTEGER NOT NULL, rel TEXT NOT NULL, size INTEGER NOT NULL, mtime INTEGER NOT NULL, PRIMARY KEY (folder, rel)) WITHOUT ROWID;
CREATE TABLE tags ( folder INTEGER NOT NULL, rel TEXT NOT NULL, n INTEGER NOT NULL, raw TEXT NOT NULL, name TEXT, value TEXT NOT NULL, PRIMARY KEY (folder, rel, n)) WITHOUT ROWID;
CREATE TABLE source_ids ( source TEXT NOT NULL, track_id TEXT NOT NULL, library TEXT NOT NULL, folder INTEGER NOT NULL, rel TEXT NOT NULL, seen INTEGER NOT NULL, PRIMARY KEY (source, track_id)) WITHOUT ROWID;
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE tracks (id INTEGER PRIMARY KEY AUTOINCREMENT, born INTEGER NOT NULL, retired_at INTEGER);
CREATE TABLE analysis ( folder INTEGER NOT NULL, rel TEXT NOT NULL, size INTEGER NOT NULL, mtime INTEGER NOT NULL, version INTEGER NOT NULL, duration_secs REAL, loudness_lufs REAL, track_gain_db REAL, track_peak REAL, bpm REAL, bpm_confidence REAL, waveform BLOB, blocks TEXT, analysed_at INTEGER NOT NULL, complete INTEGER, four REAL, PRIMARY KEY (folder, rel)) WITHOUT ROWID;
CREATE TABLE analysis_shape ( folder INTEGER NOT NULL, rel TEXT NOT NULL, waveform BLOB, blocks BLOB, beats BLOB, bands BLOB, beats_by INTEGER, band_wave BLOB, spectrum BLOB, PRIMARY KEY (folder, rel));
CREATE TABLE audiomuse ( track INTEGER PRIMARY KEY, energy REAL, key TEXT, style TEXT, moods TEXT, embedding BLOB);
CREATE TABLE beat_this ( folder INTEGER NOT NULL, rel TEXT NOT NULL, size INTEGER NOT NULL, mtime INTEGER NOT NULL, beats BLOB NOT NULL, downbeats BLOB NOT NULL, at INTEGER NOT NULL, meter INTEGER, meter_sure REAL, PRIMARY KEY (folder, rel)) WITHOUT ROWID;
CREATE INDEX source_ids_by_file ON source_ids (folder, rel);
CREATE INDEX files_by_track ON files (track);
-- A library that changed place: 0.15's folder ids were places in a sorted list, and its `set_folders` took `analysis` along and
-- left these behind, so Far Bank's shape and beats lie at the folder its library had.
-- And the other way round, as a library can go back: Just Arrived's lie at the second place, and its library at the first.
-- What no list shows (CR13): a file gone a while, one in a trash, one in a folder parked before folders had ids for life. Their days
-- lie far ahead: a server keeps such rows only so long, and a test must not meet that day.
